shared_html.shared_css:
/* ============== Shared header / footer ============== */

.site-nav,
.site-footer {
  font-family: "EB Garamond", Georgia, serif;
  color: var(--text);
}

/* ---------- HEADER ---------- */

.site-nav {
  background: var(--bg);
  border-bottom: 1px solid color-mix(in srgb, var(--primary) 30%, transparent);
  position: relative;
}

.site-nav__band {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.4rem 2rem;
  font-size: 0.78rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--bg);
  background: var(--primary);
}

.site-nav__kicker,
.site-nav__date {
  font-family: "Marcellus", "EB Garamond", serif;
}

.site-nav__date {
  color: var(--accent);
}

.site-nav__wordmark {
  display: flex;
  justify-content: center;
  padding: 1.6rem 1rem 0.8rem;
}

.site-nav__logo {
  display: inline-flex;
  align-items: center;
  gap: 0.9rem;
  text-decoration: none;
  color: var(--primary);
}

.site-nav__seal {
  color: var(--accent);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  animation: seal-breathe 3s ease-in-out infinite;
  transform-origin: center;
}

@keyframes seal-breathe {
  0%, 100% { transform: scale(1); }
  50%      { transform: scale(1.18); }
}

.site-nav__title {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  line-height: 1.1;
}

.site-nav__title-main {
  font-family: "Marcellus", serif;
  font-size: 1.6rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--primary);
}

.site-nav__title-sub {
  margin-top: 0.25rem;
  font-style: italic;
  font-size: 0.95rem;
  color: var(--secondary);
  letter-spacing: 0.05em;
}

.site-nav__primary {
  display: flex;
  justify-content: center;
  padding: 0.5rem 1rem 1rem;
}

.site-nav__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem 0;
  justify-content: center;
  align-items: center;
}

.site-nav__list li + li::before {
  content: "✦";
  color: var(--accent);
  margin: 0 0.9rem;
  font-size: 0.7rem;
  vertical-align: middle;
}

.site-nav__list a {
  font-family: "Marcellus", serif;
  text-transform: uppercase;
  letter-spacing: 0.18em;
  font-size: 0.82rem;
  text-decoration: none;
  color: var(--primary);
  padding: 0.3rem 0.2rem;
  border-bottom: 1px solid transparent;
  transition: color 180ms ease, border-color 180ms ease;
}

.site-nav__list a:hover,
.site-nav__list a:focus {
  color: var(--text-emphasis);
  border-bottom-color: var(--accent);
}

.site-nav__filet {
  height: 10px;
  background:
    linear-gradient(var(--accent), var(--accent)) center/100% 1px no-repeat,
    repeating-linear-gradient(
      90deg,
      var(--primary) 0 12px,
      var(--secondary) 12px 14px,
      var(--primary) 14px 26px,
      var(--accent) 26px 28px
    );
  border-top: 1px solid var(--primary);
  border-bottom: 1px solid var(--primary);
}

/* ---------- FOOTER ---------- */

.site-footer {
  margin-top: 4rem;
  background: var(--primary);
  color: var(--bg);
  position: relative;
}

.site-footer__filet {
  height: 12px;
  background:
    linear-gradient(var(--accent), var(--accent)) center/100% 1px no-repeat,
    repeating-linear-gradient(
      90deg,
      var(--primary) 0 14px,
      var(--secondary) 14px 16px,
      var(--primary) 16px 30px,
      var(--accent) 30px 32px
    );
  border-bottom: 1px solid var(--accent);
}

.site-footer__inner {
  max-width: 1100px;
  margin: 0 auto;
  padding: 3rem 2rem 1.5rem;
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2.5rem;
}

.site-footer__heading {
  font-family: "Marcellus", serif;
  font-size: 0.95rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--accent);
  margin: 0 0 0.9rem;
  padding-bottom: 0.5rem;
  border-bottom: 1px solid color-mix(in srgb, var(--accent) 50%, transparent);
}

.site-footer__col p {
  line-height: 1.7;
  font-size: 0.98rem;
  margin: 0;
  color: color-mix(in srgb, var(--bg) 92%, var(--secondary));
}

.site-footer__col em {
  color: var(--accent);
  font-style: italic;
}

.site-footer__list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.site-footer__list li {
  padding: 0.2rem 0;
  border-bottom: 1px dotted color-mix(in srgb, var(--accent) 35%, transparent);
}

.site-footer__list li:last-child { border-bottom: none; }

.site-footer__list a {
  color: var(--bg);
  text-decoration: none;
  font-size: 0.95rem;
  letter-spacing: 0.04em;
  transition: color 180ms ease;
}

.site-footer__list a:hover,
.site-footer__list a:focus {
  color: var(--accent);
}

.site-footer__seal {
  display: flex;
  justify-content: center;
  color: var(--accent);
  padding: 0.5rem 0 0.25rem;
}

.site-footer__band {
  text-align: center;
  font-family: "Marcellus", serif;
  text-transform: uppercase;
  letter-spacing: 0.2em;
  font-size: 0.75rem;
  color: color-mix(in srgb, var(--bg) 80%, var(--accent));
  padding: 0.75rem 1rem 1.5rem;
  display: flex;
  gap: 0.75rem;
  justify-content: center;
  flex-wrap: wrap;
}

.site-footer__band span:nth-child(2) {
  color: var(--accent);
}

/* ---------- Responsive ---------- */

@media (max-width: 820px) {
  .site-nav__band {
    flex-direction: column;
    gap: 0.25rem;
    text-align: center;
    padding: 0.55rem 1rem;
  }
  .site-nav__title-main { font-size: 1.3rem; }
  .site-nav__list { flex-direction: column; }
  .site-nav__list li + li::before { display: none; }
  .site-nav__list a {
    display: block;
    padding: 0.5rem 0.2rem;
  }
  .site-footer__inner {
    grid-template-columns: 1fr;
    gap: 1.75rem;
    padding: 2rem 1.5rem 1rem;
  }
}
